import React, { useContext, useState, useMemo, useEffect } from 'react';
import { ProductsContext } from '../context/ProductsContext';
import { CartContext } from '../context/CartContext';
import ProductCard from '../components/ProductCard';
import PopularProducts from '../components/PopularProducts';
import Reviews from '../components/Reviews';
import PromoPopup from '../components/PromoPopup';
import { Link } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const { products, promo, loading } = useContext(ProductsContext);
  const { addToCart } = useContext(CartContext);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('Все');
  const [activeTab, setActiveTab] = useState('all');
  const [showPromo, setShowPromo] = useState(false);

  const categories = useMemo(() => {
    const cats = products.map(p => p.category);
    return ['Все', ...new Set(cats)];
  }, [products]);

  const filteredProducts = useMemo(() => {
    return products.filter(product => {
      const matchesSearch = product.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = category === 'Все' || product.category === category;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, category]);

  // Логика показа попапа
  useEffect(() => {
    if (!promo?.bannerEnabled) return;

    const hasClosedPopup = localStorage.getItem('promoPopupClosed');
    if (hasClosedPopup) return;

    const timer = setTimeout(() => {
      setShowPromo(true);
    }, 3000);

    return () => clearTimeout(timer);
  }, [promo?.bannerEnabled]);

  const handleClosePromo = () => {
    setShowPromo(false);
    localStorage.setItem('promoPopupClosed', 'true');
  };

  if (loading) {
    return <div className="loader">🌸 Загружаем цветы...</div>;
  }

  return (
    <div className="home">
      <div className="video-background">
        <video autoPlay loop muted playsInline>
          <source src="/video/background.mp4" type="video/mp4" />
        </video>
        <div className="video-overlay"></div>
      </div>

      {/* Попап акции */}
      {promo?.bannerEnabled && (
        <PromoPopup 
          isOpen={showPromo} 
          onClose={handleClosePromo} 
          promo={promo}
        />
      )}

      <section className="hero">
        <div className="hero-content">
          <h1 className="hero-title">
            Свежие цветы<br />с любовью
          </h1>
          <p className="hero-subtitle">Доставка по Астане за 2 часа</p>
          <div className="hero-buttons">
            <Link to="/cart" className="hero-btn primary">
              📱 Заказать сейчас
            </Link>
            <button 
              className="hero-btn secondary"
              onClick={() => {
                document.querySelector('.filters')?.scrollIntoView({ 
                  behavior: 'smooth' 
                });
              }}
            >
              👉 Смотреть букеты
            </button>
          </div>
        </div>
      </section>

      <div className="home-tabs">
        <button 
          className={`tab-btn ${activeTab === 'all' ? 'active' : ''}`}
          onClick={() => setActiveTab('all')}
        >
          Все товары
        </button>
        <button 
          className={`tab-btn ${activeTab === 'popular' ? 'active' : ''}`}
          onClick={() => setActiveTab('popular')}
        >
          🔥 Популярные
        </button>
        <button 
          className={`tab-btn ${activeTab === 'reviews' ? 'active' : ''}`}
          onClick={() => setActiveTab('reviews')}
        >
          💬 Отзывы
        </button>
      </div>

      {activeTab === 'reviews' ? (
        <Reviews />
      ) : (
        <>
          {activeTab === 'popular' && <PopularProducts onAddToCart={addToCart} />}
          
          <section className="filters">
            <input
              type="text"
              placeholder="🔍 Поиск букета..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="search-input"
            />
            
            <div className="categories">
              {categories.map(cat => (
                <button
                  key={cat}
                  className={`category-btn ${category === cat ? 'active' : ''}`}
                  onClick={() => setCategory(cat)}
                >
                  {cat}
                </button>
              ))}
            </div>
          </section>

          {filteredProducts.length === 0 ? (
            <div className="no-products">
              <p>😔 Товаров не найдено</p>
            </div>
          ) : (
            <section className="products-grid">
              {filteredProducts.map(product => (
                <ProductCard
                  key={product.id}
                  product={product}
                  onAddToCart={addToCart}
                  showViews={true}
                  firstOrderDiscount={promo?.firstOrderDiscount}
                />
              ))}
            </section>
          )}
        </>
      )}
    </div>
  );
};

export default Home;