import React, { useState } from 'react';
import { FiStar, FiThumbsUp, FiMessageCircle } from 'react-icons/fi';
import './Reviews.css';

const Reviews = () => {
  const [reviews, setReviews] = useState([
    { 
      id: 1, 
      name: 'Айгуль', 
      text: 'Заказывала букет на годовщину свадьбы. Цветы свежие, доставили точно в указанное время. Очень довольна!', 
      rating: 5,
      date: '2024-03-15',
      likes: 12
    },
    { 
      id: 2, 
      name: 'Марат', 
      text: 'Решил порадовать жену просто так. Выбрал букет из пионов, она была в восторге! Спасибо за быструю доставку.', 
      rating: 5,
      date: '2024-03-14',
      likes: 8
    },
    { 
      id: 3, 
      name: 'Дина', 
      text: 'Очень приятные цены, качество отличное. Заказываю уже второй раз, всегда свежие цветы. Рекомендую!', 
      rating: 4,
      date: '2024-03-13',
      likes: 5
    },
    { 
      id: 4, 
      name: 'Арман', 
      text: 'Заказывал букет для мамы, ей очень понравилась композиция. Курьер вежливый, доставка быстрая.', 
      rating: 5,
      date: '2024-03-12',
      likes: 7
    }
  ]);

  const [showForm, setShowForm] = useState(false);
  const [newReview, setNewReview] = useState({ name: '', text: '', rating: 5 });

  const handleSubmitReview = (e) => {
    e.preventDefault();
    if (!newReview.name || !newReview.text) {
      alert('Заполните имя и отзыв!');
      return;
    }

    const review = {
      id: Date.now(),
      ...newReview,
      date: new Date().toISOString().split('T')[0],
      likes: 0
    };

    setReviews([review, ...reviews]);
    setNewReview({ name: '', text: '', rating: 5 });
    setShowForm(false);
  };

  const handleLike = (id) => {
    setReviews(reviews.map(review => 
      review.id === id 
        ? { ...review, likes: review.likes + 1 } 
        : review
    ));
  };

  return (
    <div className="reviews-section">
      <div className="reviews-header">
        <h2 className="reviews-title">💬 Отзывы наших клиентов</h2>
        <p className="reviews-subtitle">Более 150 довольных клиентов уже оценили наши цветы</p>
        <button 
          className="add-review-btn"
          onClick={() => setShowForm(!showForm)}
        >
          <FiMessageCircle /> Оставить отзыв
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmitReview} className="review-form">
          <h3>Напишите свой отзыв</h3>
          
          <div className="form-group">
            <label>Ваше имя</label>
            <input
              type="text"
              value={newReview.name}
              onChange={(e) => setNewReview({...newReview, name: e.target.value})}
              placeholder="Например: Айгуль"
              required
            />
          </div>

          <div className="form-group">
            <label>Оценка</label>
            <div className="rating-stars">
              {[1, 2, 3, 4, 5].map(star => (
                <FiStar
                  key={star}
                  className={`star ${star <= newReview.rating ? 'filled' : ''}`}
                  onClick={() => setNewReview({...newReview, rating: star})}
                />
              ))}
            </div>
          </div>

          <div className="form-group">
            <label>Ваш отзыв</label>
            <textarea
              value={newReview.text}
              onChange={(e) => setNewReview({...newReview, text: e.target.value})}
              placeholder="Расскажите о вашем опыте..."
              rows="4"
              required
            />
          </div>

          <div className="form-buttons">
            <button type="submit" className="submit-review-btn">
              Отправить отзыв
            </button>
            <button 
              type="button" 
              className="cancel-review-btn"
              onClick={() => setShowForm(false)}
            >
              Отмена
            </button>
          </div>
        </form>
      )}

      <div className="reviews-grid">
        {reviews.map(review => (
          <div key={review.id} className="review-card">
            <div className="review-header">
              <div>
                <span className="review-name">{review.name}</span>
                <span className="review-date">{review.date}</span>
              </div>
              <div className="review-rating">
                {[...Array(5)].map((_, i) => (
                  <FiStar 
                    key={i} 
                    className={i < review.rating ? 'star filled' : 'star'} 
                  />
                ))}
              </div>
            </div>
            <p className="review-text">"{review.text}"</p>
            <div className="review-footer">
              <button 
                className="like-btn"
                onClick={() => handleLike(review.id)}
              >
                <FiThumbsUp /> {review.likes}
              </button>
            </div>
          </div>
        ))}
      </div>

      <div className="reviews-stats">
        <div className="stat-item">
          <span className="stat-value">4.8</span>
          <span className="stat-label">Средняя оценка</span>
        </div>
        <div className="stat-item">
          <span className="stat-value">150+</span>
          <span className="stat-label">Отзывов</span>
        </div>
        <div className="stat-item">
          <span className="stat-value">98%</span>
          <span className="stat-label">Рекомендуют</span>
        </div>
      </div>
    </div>
  );
};

export default Reviews;