import React, { useState, useContext } from 'react';
import { FiShoppingCart, FiEye, FiStar } from 'react-icons/fi';
import { ProductsContext } from '../context/ProductsContext';
import { CartContext } from '../context/CartContext';
import toast from 'react-hot-toast';
import './ProductCard.css';

const ProductCard = ({ product, onAddToCart, showViews = false, firstOrderDiscount }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [isAdded, setIsAdded] = useState(false);
  const { incrementViews } = useContext(ProductsContext);
  const { cart } = useContext(CartContext);

  // Определяем, применять ли скидку на первый заказ
  const isFirstOrder = cart.length === 0; // если корзина пуста, считаем что это первый заказ
  const finalPrice = (isFirstOrder && firstOrderDiscount)
    ? Math.round(product.price * (1 - firstOrderDiscount / 100))
    : product.price;

  const handleAddToCart = () => {
    // Передаём в корзину товар с учётом возможной скидки
    onAddToCart({ ...product, price: finalPrice });
    toast.success('🌸 Товар добавлен в корзину!', {
      icon: '✅',
    });
    setIsAdded(true);
    setTimeout(() => setIsAdded(false), 1000);
  };

  const handleCardClick = () => {
    incrementViews(product.id);
  };

  // Вычисляем процент скидки, если есть oldPrice
  const discountPercent = product.oldPrice
    ? Math.round((1 - product.price / product.oldPrice) * 100)
    : 0;

  return (
    <div 
      className={`product-card ${isHovered ? 'hovered' : ''}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onClick={handleCardClick}
    >
      <div className="product-image-container">
        <img 
          src={product.imageUrl || 'https://via.placeholder.com/300'} 
          alt={product.name}
          className="product-image"
        />
        {showViews && product.views > 0 && (
          <div className="product-views">
            <FiEye /> {product.views}
          </div>
        )}
        {product.isHit && (
          <div className="product-hit">
            <FiStar /> Хит
          </div>
        )}
        {discountPercent > 0 && (
          <div className="product-discount">
            -{discountPercent}%
          </div>
        )}
      </div>
      <div className="product-info">
        <h3 className="product-name">{product.name}</h3>
        <div className="product-price-container">
          {product.oldPrice ? (
            <>
              <span className="old-price">{product.oldPrice.toLocaleString()} ₸</span>
              <span className="current-price">{finalPrice.toLocaleString()} ₸</span>
            </>
          ) : (
            <span className="current-price">{finalPrice.toLocaleString()} ₸</span>
          )}
          {isFirstOrder && firstOrderDiscount > 0 && !product.oldPrice && (
            <span className="first-order-badge">-{firstOrderDiscount}%</span>
          )}
        </div>
        <p className="product-category">{product.category}</p>
        <button 
          className={`add-to-cart-btn ${isAdded ? 'added' : ''}`}
          onClick={(e) => {
            e.stopPropagation();
            handleAddToCart();
          }}
        >
          <FiShoppingCart />
          {isAdded ? ' Добавлено' : ' В корзину'}
        </button>
      </div>
    </div>
  );
};

export default React.memo(ProductCard);