import React, { useEffect, useState } from 'react';
import { FiPercent, FiX } from 'react-icons/fi';
import './PromoPopup.css';

const PromoPopup = ({ isOpen, onClose, promo }) => {
  const [timeLeft, setTimeLeft] = useState(null);

  useEffect(() => {
    if (promo?.promoEndDate) {
      const interval = setInterval(() => {
        const diff = promo.promoEndDate - Date.now();
        if (diff <= 0) {
          setTimeLeft(null);
          clearInterval(interval);
        } else {
          const days = Math.floor(diff / (1000 * 60 * 60 * 24));
          const hours = Math.floor((diff / (1000 * 60 * 60)) % 24);
          const minutes = Math.floor((diff / 1000 / 60) % 60);
          const seconds = Math.floor((diff / 1000) % 60);
          setTimeLeft({ days, hours, minutes, seconds });
        }
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [promo?.promoEndDate]);

  if (!isOpen) return null;

  return (
    <div className="popup-overlay">
      <div className="popup-content">
        <button className="popup-close" onClick={onClose}>
          <FiX />
        </button>
        
        <div className="popup-icon">
          <FiPercent />
        </div>
        
        <h2 className="popup-title">Специальное предложение!</h2>
        
        <p className="popup-text">{promo?.bannerText || 'Скидка на первый заказ'}</p>
        
        {timeLeft && (
          <div className="popup-timer">
            <div className="timer-item">
              <span className="timer-value">{timeLeft.days}</span>
              <span className="timer-label">дней</span>
            </div>
            <div className="timer-item">
              <span className="timer-value">{timeLeft.hours}</span>
              <span className="timer-label">часов</span>
            </div>
            <div className="timer-item">
              <span className="timer-value">{timeLeft.minutes}</span>
              <span className="timer-label">минут</span>
            </div>
            <div className="timer-item">
              <span className="timer-value">{timeLeft.seconds}</span>
              <span className="timer-label">секунд</span>
            </div>
          </div>
        )}
        
        <button className="popup-button" onClick={onClose}>
          Понятно, спасибо!
        </button>
      </div>
    </div>
  );
};

export default PromoPopup;